CREATE TABLE game (id BIGINT NOT NULL AUTO_INCREMENT,slug VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(160) NOT NULL,summary VARCHAR(500) NOT NULL DEFAULT '',description MEDIUMTEXT NOT NULL DEFAULT (''),developer VARCHAR(160) NOT NULL DEFAULT '',publisher VARCHAR(160) NOT NULL DEFAULT '',release_date DATE NULL,cover_url TEXT NOT NULL DEFAULT (''),status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_game_slug UNIQUE(slug),KEY idx_game_public(status,id DESC),CONSTRAINT ck_game_slug CHECK(REGEXP_LIKE(slug,'^[a-z0-9-]{3,64}$','c')),CONSTRAINT ck_game_name CHECK(CHAR_LENGTH(TRIM(name)) BETWEEN 1 AND 160),CONSTRAINT ck_game_summary CHECK(CHAR_LENGTH(summary)<=500),CONSTRAINT ck_game_description CHECK(CHAR_LENGTH(description)<=20000),CONSTRAINT ck_game_status CHECK(status IN ('active','inactive'))) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
